USE enlazate;
CREATE TABLE suppliers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(190) NOT NULL, contact_name VARCHAR(120) NULL, phone VARCHAR(40) NULL, email VARCHAR(190) NULL, address VARCHAR(255) NULL, services TEXT NULL, materials TEXT NULL, usual_lead_time_days SMALLINT UNSIGNED NULL, notes TEXT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE supplier_quotes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, supplier_id BIGINT UNSIGNED NOT NULL, order_id BIGINT UNSIGNED NULL, amount_dop DECIMAL(12,2) NOT NULL, valid_until DATE NULL, status ENUM('requested','received','accepted','rejected') NOT NULL DEFAULT 'requested', notes TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE CASCADE, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE SET NULL);
CREATE TABLE production_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NULL, supplier_id BIGINT UNSIGNED NULL, production_number VARCHAR(30) NOT NULL UNIQUE, status ENUM('draft','sent','in_production','received','closed','cancelled') NOT NULL DEFAULT 'draft', instructions TEXT NULL, internal_cost_dop DECIMAL(12,2) NULL, sent_at DATETIME NULL, expected_at DATE NULL, received_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE SET NULL, FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL);
CREATE TABLE production_order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, production_order_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NULL, product_name VARCHAR(190) NOT NULL, quantity INT UNSIGNED NOT NULL, width_mm DECIMAL(8,2) NULL, height_mm DECIMAL(8,2) NULL, qr_width_mm DECIMAL(8,2) NULL, material VARCHAR(120) NULL, finish VARCHAR(120) NULL, FOREIGN KEY(production_order_id) REFERENCES production_orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL);
CREATE TABLE files (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NULL, production_order_id BIGINT UNSIGNED NULL, original_name VARCHAR(255) NOT NULL, storage_name VARCHAR(255) NOT NULL UNIQUE, mime_type VARCHAR(120) NOT NULL, size_bytes BIGINT UNSIGNED NOT NULL, visibility ENUM('private','public') NOT NULL DEFAULT 'private', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE SET NULL, FOREIGN KEY(production_order_id) REFERENCES production_orders(id) ON DELETE SET NULL);
CREATE TABLE design_templates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(190) NOT NULL, product_type VARCHAR(100) NOT NULL, width_mm DECIMAL(8,2) NOT NULL, height_mm DECIMAL(8,2) NOT NULL, bleed_mm DECIMAL(8,2) NOT NULL DEFAULT 3, safe_margin_mm DECIMAL(8,2) NOT NULL DEFAULT 5, qr_width_mm DECIMAL(8,2) NULL, definition JSON NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE design_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NULL, template_id BIGINT UNSIGNED NULL, version_no INT UNSIGNED NOT NULL DEFAULT 1, name VARCHAR(190) NOT NULL, width_mm DECIMAL(8,2) NOT NULL, height_mm DECIMAL(8,2) NOT NULL, definition JSON NOT NULL, preview_file_id BIGINT UNSIGNED NULL, print_file_id BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE SET NULL, FOREIGN KEY(template_id) REFERENCES design_templates(id) ON DELETE SET NULL, FOREIGN KEY(preview_file_id) REFERENCES files(id) ON DELETE SET NULL, FOREIGN KEY(print_file_id) REFERENCES files(id) ON DELETE SET NULL);
